-- Profile iplant-block-extraction-v1; SELECT only. Bind @EstateID, @FromDate, @ToDate and @Year.
SELECT YEAR(DDate) Year,COUNT(*) Records,COUNT(DISTINCT BlockID) Blocks,COUNT(DISTINCT StationID) Stations,MIN(DDate) FirstDate,MAX(DDate) LastDate FROM Checkroll.RainFall WHERE EstateID=@EstateID GROUP BY YEAR(DDate) ORDER BY Year;
SELECT a.AYear Year,a.AMonth Month,COUNT(*) Rows,COUNT(DISTINCT c.Block) RawBlockIDs,COUNT(DISTINCT b.BlockID) MatchedBlocks,SUM(CASE WHEN b.BlockID IS NOT NULL THEN c.DebitValue ELSE 0 END) BlockDebits,SUM(CASE WHEN b.BlockID IS NOT NULL THEN c.CreditValue ELSE 0 END) BlockCredits FROM dbo.CheckrollTemp c JOIN General.ActiveMonthYear a ON a.ActiveMonthYearID=c.ActiveMonthYear AND a.EstateID=c.Location LEFT JOIN General.BlockMaster b ON b.BlockID=c.Block AND b.EstateID=c.Location WHERE c.Location=@EstateID GROUP BY a.AYear,a.AMonth ORDER BY Year,Month;
SELECT a.AYear Year,COUNT(*) Rows,MIN(r.CreatedOn) FirstCreated,MAX(r.CreatedOn) LastCreated FROM Checkroll.DailyReceiption r LEFT JOIN General.ActiveMonthYear a ON a.ActiveMonthYearID IS NULL WHERE r.EstateID=@EstateID AND NOT EXISTS(SELECT 1 FROM Checkroll.DailyAttendance d WHERE d.DailyReceiptionID=r.DailyReceiptionID AND d.EstateID=r.EstateID) GROUP BY a.AYear;
SELECT YEAR(h.RGNDate) Year,h.Status,c.STCategoryDescp,u.UOM,COUNT(*) Rows,SUM(d.ReturnQty) ReturnQty,SUM(d.ReturnedValue) ReturnedValue FROM Store.STReturnGoodsDetails d JOIN Store.STReturnGoodsNote h ON h.STReturnGoodsNoteID=d.STReturnGoodsNoteID AND h.EstateID=d.EstateID LEFT JOIN Store.STMaster s ON s.StockID=d.StockID AND s.EstateID=d.EstateID LEFT JOIN Store.STCategory c ON c.STCategoryID=s.STCategoryID AND c.EstateID=s.EstateID LEFT JOIN General.UOM u ON u.UOMID=s.UOMID WHERE d.EstateID=@EstateID GROUP BY YEAR(h.RGNDate),h.Status,c.STCategoryDescp,u.UOM ORDER BY Year;
SELECT TOP (10) i.SIVDate,i.SIVNO,b.BlockName,s.StockCode,s.StockDesc,u.UOM,s.Convertion,d.IssuedQty,d.IssueUnitPrice,d.IssuedValue FROM Store.STIssueDetails d JOIN Store.STIssue i ON i.STIssueID=d.STIssueID AND i.EstateID=d.EstateID JOIN Store.STMaster s ON s.StockID=d.StockID AND s.EstateID=d.EstateID LEFT JOIN General.UOM u ON u.UOMID=s.UOMID LEFT JOIN General.BlockMaster b ON b.BlockID=d.BlockID AND b.EstateID=d.EstateID WHERE d.EstateID=@EstateID AND s.StockDesc LIKE 'GANO EF%' AND i.SIVDate>=@FromDate AND i.SIVDate<@ToDate ORDER BY i.SIVDate;
SELECT TOP (8) i.SIVDate,i.SIVNO,b.BlockName,c.STCategoryDescp,s.StockDesc,u.UOM,d.IssuedQty,d.IssueUnitPrice,d.IssuedValue FROM Store.STIssueDetails d JOIN Store.STIssue i ON i.STIssueID=d.STIssueID AND i.EstateID=d.EstateID JOIN Store.STMaster s ON s.StockID=d.StockID AND s.EstateID=d.EstateID JOIN Store.STCategory c ON c.STCategoryID=s.STCategoryID AND c.EstateID=s.EstateID LEFT JOIN General.UOM u ON u.UOMID=s.UOMID LEFT JOIN General.BlockMaster b ON b.BlockID=d.BlockID AND b.EstateID=d.EstateID WHERE d.EstateID=@EstateID AND c.STCategoryCode IN ('ST04','ST12') AND i.SIVDate>=@FromDate AND i.SIVDate<@ToDate AND i.Status='APPROVED' ORDER BY i.SIVDate DESC,i.SIVNO,b.BlockName;
SELECT s.name SchemaName,p.name ProcedureName,m.definition FROM sys.procedures p JOIN sys.schemas s ON s.schema_id=p.schema_id JOIN sys.sql_modules m ON m.object_id=p.object_id WHERE p.name IN ('AllLedgerCOAReport','CropStatementSummaryReport','CropStatementReportCepat');
SELECT AYear,AMonth,COUNT(*) Rows,COUNT(DISTINCT BlockID) Blocks FROM Accounts.BlockMasterHistory WHERE EstateID=@EstateID GROUP BY AYear,AMonth ORDER BY AYear,AMonth;
SELECT DISTINCT CurrencyID FROM Accounts.COA WHERE EstateID=@EstateID;
SELECT 'Orphan checkroll accounting period' Issue,COUNT(*) Rows FROM dbo.CheckrollTemp c WHERE c.Location=@EstateID AND NOT EXISTS(SELECT 1 FROM General.ActiveMonthYear a WHERE a.ActiveMonthYearID=c.ActiveMonthYear AND a.EstateID=c.Location)
UNION ALL SELECT 'Orphan stock issue detail',COUNT(*) FROM Store.STIssueDetails d WHERE d.EstateID=@EstateID AND NOT EXISTS(SELECT 1 FROM Store.STIssue i WHERE i.STIssueID=d.STIssueID AND i.EstateID=d.EstateID);
